 def _pseudo_parse_arglist(signode: desc_signature, arglist: str) -> None:
     """"Parse" a list of arguments separated by commas.

     Arguments can have "default" values.  Keep track of the "has default"
     state, and accept a comma without a following argument as a sign that the
     argument is a keyword-only argument.
     """
     param = None
     for part in arglist.split(','):
         part = part.strip()
         if param:
             # previous argument was a keyword-only argument
             param += ', ' + part
             continue
         if '=' in part:
             param = None
             continue
         if part in ('*', '**'):
             param = None
             continue
         if part == '/':
             param = None
             continue
         param = part

     if param:
         signode += addnodes.desc_sig_punctuation('', param)

     signode += addnodes.desc_sig_punctuation('', ')')

     return signode


