+using System;
+using System.Collections.Generic;
+using System.Linq;
+
+namespace MigrationOptimizer
+{
+    /// <summary>
+    /// Optimizes migration operations by reducing redundant AddIndex/RemoveIndex operations.
+    /// </summary>
+    public class MigrationOptimizer
+    {
+        /// <summary>
+        /// Optimizes a list of migration operations by combining and reducing
+        /// AddIndex/RemoveIndex operations where possible.
+        /// </summary>
+        /// <param name="operations">The list of migration operations to optimize.</param>
+        /// <returns>The optimized list of migration operations.</returns>
+        public IReadOnlyList<MigrationOperation> Optimize(IReadOnlyList<MigrationOperation> operations)
+        {
+            if (operations == null || operations.Count == 0)
+            {
+                return operations ?? Array.Empty<MigrationOperation>();
+            }
+
+            var result = new List<MigrationOperation>();
+            var indexOperations = new Dictionary<string, IndexOperationState>();
+
+            foreach (var operation in operations)
+            {
+                switch (operation)
+                {
+                    case AddIndexOperation addIndex:
+                        HandleAddIndex(addIndex, indexOperations, result);
+                        break;
+                    case RemoveIndexOperation removeIndex:
+                        HandleRemoveIndex(removeIndex, indexOperations, result);
+                        break;
+                    default:
+                        // Flush pending index operations before non-index operations
+                        FlushPendingIndexOperations(indexOperations, result);
+                        result.Add(operation);
+                        break;
+                }
+            }
+
+            // Flush any remaining pending index operations
+            FlushPendingIndexOperations(indexOperations, result);
+
+            return result;
+        }
+
+        private void HandleAddIndex(AddIndexOperation addIndex, 
+            Dictionary<string, IndexOperationState> indexOperations, 
+            List<MigrationOperation> result)
+        {
+            var key = GetIndexKey(addIndex.Table, addIndex.Columns);
+            
+            if (indexOperations.TryGetValue(key, out var state))
+            {
+                // If we previously removed this index, cancel both operations
+                if (state.State == IndexState.Removed)
+                {
+                    indexOperations.Remove(key);
+                    return;
+                }
+                
+                // If already added, skip duplicate
+                if (state.State == IndexState.Added)
+                {
+                    return;
+                }
+            }
+            else
+            {
+                indexOperations[key] = new IndexOperationState
+                {
+                    State = IndexState.Added,
+                    Operation = addIndex
+                };
+            }
+        }
+
+        private void HandleRemoveIndex(RemoveIndexOperation removeIndex, 
+            Dictionary<string, IndexOperationState> indexOperations, 
+            List<MigrationOperation> result)
+        {
+            var key = GetIndexKey(removeIndex.Table, removeIndex.Columns);
+            
+            if (indexOperations.TryGetValue(key, out var state))
+            {
+                // If we previously added this index, cancel both operations
+                if (state.State == IndexState.Added)
+                {
+                    indexOperations.Remove(key);
+                    return;
+                }
+                
+                // If already removed, skip duplicate
+                if (state.State == IndexState.Removed)
+                {
+                    return;
+                }
+            }
+            else
+            {
+                indexOperations[key] = new IndexOperationState
+                {
+                    State = IndexState.Removed,
+                    Operation = removeIndex
+                };
+            }
+        }
+
+        private void FlushPendingIndexOperations(
+            Dictionary<string, IndexOperationState> indexOperations, 
+            List<MigrationOperation> result)
+        {
+            foreach (var operation in indexOperations.Values)
+            {
+                result.Add(operation.Operation);
+            }
+            indexOperations.Clear();
+        }
+
+        private string GetIndexKey(string table, IEnumerable<string> columns)
+        {
+            return $"{table}:{string.Join(",", columns.OrderBy(c => c))}";
+        }
+
+        private enum IndexState
+        {
+            Added,
+            Removed
+        }
+
+        private class IndexOperationState
+        {
+            public IndexState State { get; set; }
+            public MigrationOperation Operation { get; set; }
+        }
+    }
+
+    // Base class for migration operations
+    public abstract class MigrationOperation
+    {
+        public string Table { get; set; }
+    }
+
+    public class AddIndexOperation : MigrationOperation
+    {
+        public IEnumerable<string> Columns { get; set; }
+    }
+
+    public class RemoveIndexOperation : MigrationOperation
+    {
+        public IEnumerable<string> Columns { get; set; }
+    }
+}
