+            {
+                new AddIndexOperation { Table = "Users", Columns = new[] { "Email" } },
+                new AddIndexOperation { Table = "Users", Columns = new[] { "Email" } },
+                new AddIndexOperation { Table = "Users", Columns = new[] { "Name" } }
